package com.fitlife.usuario.config;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Configuration;import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;@Configuration public class UploadConfig implements WebMvcConfigurer{private final String directory;public UploadConfig(@Value("${fitlife.uploads.directory:./uploads}")String d){directory=d;}@Override public void addResourceHandlers(ResourceHandlerRegistry r){r.addResourceHandler("/uploads/**").addResourceLocations("file:"+java.nio.file.Paths.get(directory).toAbsolutePath().normalize()+"/");}}
